content.content:
# Put a person on hold, or take them off it when held. An unknown person is a 404.
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.TogglePersonHold
  govern: [ transaction ]
  next: audit
# Last before the response: the hold is saved.
audit:
  class: net.officefloor.hq.app.person.AuditPersonHold
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or takes them off hold when they are on it. */
public class TogglePersonHold {
    public void toggle(@Val Person person, PersonRepository repository) {
        person.setHeld(!person.isHeld());
        repository.saveHeld(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the person put on hold, or released from it. Runs after it is saved. */
public class AuditPersonHold {
    public void audit(@Val Sheet sheet, @Val Person person,
            HttpServletRequest request, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + sheet.id()
                + " by=" + Audit.user(request) + " name=" + person.getName());
    }
}
