package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** A person on a sheet, as the store holds it. {@code id} is null until first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    private String grade;
    private long version;
    private int statementCount;
    private String statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    private boolean held;
    private final List<Long> patronIds = new ArrayList<>();
    private final TreeMap<LocalDate, String> datedGrades = new TreeMap<>();

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
    public String getGrade() { return grade; }
    public void setGrade(String grade) { this.grade = grade; }
    /** The grades recorded from a date, by from-date: each in force from it until the next. */
    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
    /** Record the grade from this date, replacing any recorded from the same date. */
    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
        return dated == null ? grade : dated.getValue();
    }
    /** Raised by one on each save; an edit names the version it was made from. */
    public long getVersion() { return version; }
    public void setVersion(long version) { this.version = version; }
    /** How many statements have been taken for them. */
    public int getStatementCount() { return statementCount; }
    /** The last statement's due-total (n/a when it had none); null before the first. */
    public String getStatedTotal() { return statedTotal; }
    /** The sheet's today when the last statement was taken; null before the first. */
    public LocalDate getStatementDate() { return statementDate; }
    public void setStatements(int count, String statedTotal, LocalDate statementDate) {
        this.statementCount = count;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }
    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether they are on hold: their OPEN claims count in no total until they are released. */
    public boolean isHeld() { return held; }
    public void setHeld(boolean held) { this.held = held; }
    /** The ids of the people they name as patrons, in the order named. */
    public List<Long> getPatronIds() { return patronIds; }
    /** Whether a claim on this date is refused: they are retired from an earlier date. */
    public boolean retiredBefore(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade in force from a date (yyyy-MM-dd; '' from the beginning of time) until the next one. */
export type GradeFrom = { from: string; grade: Grade };

/** The grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): Grade {
  let best = grades[0];
  for (const g of grades) if (g.from <= date && g.from >= best.from) best = g;
  return best.grade;
}

// `version` is raised by each save; an edit sends the version it was made from. `statementCount`
// is how many statements have been taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and date ('' before the first). `retired` is set once they have a retirement
// date, `retiredFrom` ('' when not retired), whatever that date is. `held` is whether they are on hold: their OPEN and PENDING claims then count in no total.
// `patronIds` are the ids of the people they name as their patrons. `grade` is the grade in force on
// the sheet's today; `grades` every grade they have been given, by from-date, the first from ''.
export type Person = {
  id: string;
  name: string;
  grade: Grade;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  patronIds: string[];
  grades: GradeFrom[];
};

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: async () =>
    (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
});

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery(peopleQuery(sheetId));
}

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet keeps it. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/**
 * A claim's status: DRAFT when made, then OPEN, then SETTLED; a clerk's settle above the clerk
 * limit makes it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim may be VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is opened; '' for a draft or a voided claim), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate), and
 * who opened it ('' until it is opened); whether its person's last statement bound it, and the
 * figure it was bound to ('' when not stated; n/a when it had none); and, for a correction (a
 * negative amount), the number of the settled claim it corrects ('' for any other claim); and the
 * date (yyyy-MM-dd) its figures round by (a correction's is the date of the claim it corrects).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  openedBy: string;
  stated: boolean;
  statedDue: string;
  corrects: string;
  roundDate: string;
  /** Its due-by (yyyy-MM-dd), fixed when it was made: its date plus its grade's terms then. */
  dueBy: string;
  /**
   * Its status log, oldest first: one line per status it has had, as
   * `<STATUS> by <user> on <date> due=<due>` (the sheet's today and its due at that moment).
   */
  log: string[];
};

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/**
 * Whether a claim's stated figure is in force: its person's last statement bound it and it is not
 * PENDING (a PENDING claim shows its live figure).
 */
export const isBound = (c: Claim) => c.stated && c.status !== 'PENDING';

/**
 * Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED
 * do, and an OPEN or PENDING one not while its person is on hold (`held`).
 */
export const counts = (c: Claim, held: boolean) => c.status === 'SETTLED' || (isOpen(c) && !held);

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: async () =>
    (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
});

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery(claimsQuery(sheetId));
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** An amount as the claim form takes it: up to two decimals, negative for a correction. */
export const CLAIM_AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/**
 * A claim number, as a correction names the claim it corrects: a sheet-wide number, or a number
 * within a period (<period name>-<n>, X-<n> for a claim in no period).
 */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/**
 * The amounts of the claims that count (OPEN, PENDING and SETTLED, but not open ones of a person on hold:
 * `held` tells by person id) added up, in whole cents so no rounding creeps in, shown with two
 * decimals.
 */
export function sumAmounts(claims: Claim[], held: (personId: string) => boolean): string {
  const cents = claims.filter((c) => counts(c, held(c.personId))).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
