package net.officefloor.hq.app.person;

/** A retirement as the screen sends it: the date the person is retired from (blank: the sheet's today). */
public record RetireRequest(String from) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated retirement: the date the person is retired from (null: the sheet's today). */
public record RetireInput(LocalDate from) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<RetireInput> body)
            throws InvalidPersonException {
        String raw = request == null || request.from() == null ? "" : request.from().trim();
        if (raw.isEmpty()) {
            body.set(new RetireInput(null));
            return;
        }
        try {
            body.set(new RetireInput(LocalDate.parse(raw)));
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("A retirement date is a date");
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date given, or the sheet's today when none is. */
public class RetirePerson {
    public void retire(@Val RetireInput input, @Val Sheet sheet, @Val Person person,
            PersonRepository repository) {
        person.setRetiredFrom(input.from() != null ? input.from() : sheet.today());
        repository.saveRetired(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the retirement. Runs after it is saved. */
public class AuditPersonRetired {
    public void audit(@Val Sheet sheet, @Val Person person,
            HttpServletRequest request, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
