  today: string,
  claims: Claim[],
  holds: Hold[],
  floor: string,
  late: Late,
): { count: number; total: string } {
  const overdue = claims.filter((c) => counts(c, holds) && isOverdue(c, today));
  return {
    count: overdue.length,
